// Full IAU 2000A nutation, radians. Bit-identical summation order to skyfield.
inline void iau2000a_rad(double jd_tt, double& dpsi, double& deps) {
    const double t = (jd_tt - 2451545.0) / 36525.0;
    double a[5];
    {
        // fundamental_arguments(t, terms=5): Horner over (fa4..fa0)
        for (int k = 0; k < 5; ++k) {
            double v = FA5[k][4];
            for (int i = 3; i >= 0; --i) v = v * t + FA5[k][i];
            double red = std::fmod(v, 1296000.0);
            if (red < 0.0) red += 1296000.0;
            a[k] = red * 4.8481368110953599e-06;
        }
    }
    double s = 0.0, e = 0.0;
    for (int i = 0; i < kLun; ++i) {
        double arg = 0.0;
        for (int k = 0; k < 5; ++k) arg += nals[i][k] * a[k];
        const double sn = std::sin(arg), cs = std::cos(arg);
        s += sn * lonc[i][0] + sn * lonc[i][1] * t + cs * lonc[i][2];
        e += cs * oblc[i][0] + cs * oblc[i][1] * t + sn * oblc[i][2];
    }
    double pa[14];
    for (int k = 0; k < 14; ++k) {
        pa[k] = ano[k][0] + ano[k][1] * t;
        if (k == 13) pa[k] *= t;
    }
    for (int i = 0; i < kPla; ++i) {
        double arg = 0.0;
        for (int k = 0; k < 14; ++k) arg += napl[i][k] * pa[k];
        const double sn = std::sin(arg), cs = std::cos(arg);
        s += sn * plonc[i][0] + cs * plonc[i][1];
        e += sn * ploblc[i][0] + cs * ploblc[i][1];
    }
    constexpr double kTenthUas2Rad = 4.8481368110953599e-06 / 1e7;
    dpsi = s * kTenthUas2Rad;
    deps = e * kTenthUas2Rad;
}
